def transform(grid):
    h, w = len(grid), len(grid[0])

    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    divider_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
    ]
    row_seps = set(divider_rows)
    col_seps = set(divider_cols)

    from collections import Counter
    counts = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in row_seps and c not in col_seps
    )
    background = counts.most_common(1)[0][0]
    marker = next(color for color in counts if color != background)

    row_groups, group = [], []
    for r in range(h):
        if r in row_seps:
            if group:
                row_groups.append(group)
                group = []
        else:
            group.append(r)
    if group:
        row_groups.append(group)

    col_groups, group = [], []
    for c in range(w):
        if c in col_seps:
            if group:
                col_groups.append(group)
                group = []
        else:
            group.append(c)
    if group:
        col_groups.append(group)

    return [
        [
            background if sum(grid[r][c] == marker for r in rs for c in cs) % 2 else 1
            for cs in col_groups
        ]
        for rs in row_groups
    ]
